  void _updateAnimationsForItem(String itemId, TransformableItem item) {
    final AnimationController controller = _animControllers[itemId]!;

    _scaleAnimations[itemId] = Tween<double>(
      begin: item.scale,
      end: 1.0,
    ).animate(controller);

    _rotationAnimations[itemId] = Tween<double>(
      begin: item.rotation,
      end: 0.0,
    ).animate(controller);

    // Use absolute offset for animations
    _offsetAnimations[itemId] = Tween<Offset>(
      begin: _relativeToAbsoluteOffset(item.relativeOffset),
      end: Offset.zero,
    ).animate(controller);
