                  final Offset delta =
                      details.localFocalPoint - _lastSingleFingerPosition;
                  _lastSingleFingerPosition = details.localFocalPoint;

                  setState(() {
                    // Convert absolute delta to relative delta
                    final Offset relativeDelta = Offset(
